arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Search for 'Individual income tax' in the content
for page in data['pages']:
    page_id = page['id']
    if 'elements' in page:
        for elem in page['elements']:
            if 'content' in elem and elem['content']:
                content = str(elem['content'])
                if 'Individual' in content and 'income' in content and 'tax' in content:
                    print(f'Page {page_id}: {content}')
" | head -50
